  display: flex;
  flex-direction: column;
}

/* ── Header ── */
header {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  padding: 0 32px;
  height: 60px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.logo {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--color-accent);
  letter-spacing: -0.3px;
}

.breadcrumb {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.875rem;
  color: var(--color-text-secondary);
}

.breadcrumb span { color: var(--color-text-primary); font-weight: 500; }

/* ── Main layout ── */
main {
  flex: 1;
  max-width: 900px;
  width: 100%;
  margin: 48px auto;
  padding: 0 24px;
}

.page-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 4px;
}

.page-subtitle {
  font-size: 0.9rem;
  color: var(--color-text-secondary);
  margin-bottom: 32px;
}

